        if (equalsText(candidateValue, baseValue)) {
            return currentValue;
        }
        if (equalsText(currentValue, baseValue) || equalsText(candidateValue, currentValue)) {
            return candidateValue;
        }
        conflicts.add(field);
        return currentValue;
    }

    /**
