            repository.deleteDedup(requestId);
            throw ex;
        }
    }

    private WriteResult replayOrReject(DedupRecord record, String requestHash) {
        if (!record.getRequestHash().equals(requestHash)) {
            throw new ConflictException("相同 requestId 的请求参数不一致");
        }
