        repository.insertVersion(snapshot);
    } catch (DuplicateKeyException ex) {
        // 极端并发下抢占失败，基于提交时最新版本重新判定。
        ObservationSnapshot latest = repository.findLatest(request.getObservationId()).orElseThrow();
        if (latest.isDeleted()) {
